UNION
    w : WORD;
    b : ARRAY[0..1] OF BYTE;
END_UNION
END_TYPE

ST.xhtml:
F_Convert := REAL_TO_INT(rIn);
iSum := iA + iB;
IF iB <> 0 THEN
    iQuot := iA / iB;
ELSE
    iQuot := 0;
END_IF
iMux := MUX(iSel, 10, 20, 30);
iLim := LIMIT(iMn, F_Convert, iMx);

InterfaceAsPlainText.xhtml:
// F_Convert — пересчёт аналоговой уставки дозатора коагулянта (ST, FUNCTION).
//
// Поведение (по нему считает модель scenarios/reference/model_F_Convert.py):
// - результат функции — REAL_TO_INT(rIn): половина округляется от нуля (2.5 → 3, −2.5 → −3; проба M0);
// - iSum := iA + iB с переносом INT (32767 + 1 = −32768);
// - iQuot := iA / iB с отбрасыванием дробной части к нулю, при iB = 0 — 0 (делитель-переменная → C2S7-SEM-DIV0);
// - iMux := MUX(iSel, 10, 20, 30), iSel ∈ 0…2;
// - iLim := LIMIT(iMn, результат, iMx); при MN > MX результат — MX (проба M0: LIMIT(10, 5, 0) = 0).
FUNCTION F_Convert : INT
VAR_INPUT
    rIn : REAL;
    iA : INT;
    iB : INT;
    iSel : INT;
    iMn : INT;
    iMx : INT;
END_VAR
VAR_OUTPUT
    iSum : INT;
    iQuot : INT;
    iMux : INT;
    iLim : INT;
END_VAR

ST.xhtml:
fbSr(SET1 := xSet, RESET := xReset, Q1 => xSr);
fbRs(SET := xSet, RESET1 := xReset, Q1 => xRs);
fbCtu(CU := xCu, RESET := xReset, PV := 3, Q => xCuQ, CV => wCu);
fbCtd(CD := xCd, LOAD := xLoad, PV := 2, Q => xCdQ, CV => wCd);
fbRise(CLK := xClk, Q => xRise);
fbFall(CLK := xClk, Q => xFall);

InterfaceAsPlainText.xhtml:
// FB_Latch — фиксация команд пульта фильтра (ST, FUNCTION_BLOCK).
//
// Поведение (модель scenarios/reference/model_FB_Latch.py):
// - xSr — SR(SET1 := xSet, RESET := xReset): установка доминирует, при SET = RESET = 1 → TRUE;
// - xRs — RS(SET := xSet, RESET1 := xReset): сброс доминирует, при SET = RESET = 1 → FALSE
//   (одноимённые блоки S7 — наоборот: C2S7-SEM-SRRS, CDS_SR/CDS_RS);
// - CTU(CU := xCu, RESET := xReset, PV := 3): wCu — счёт фронтов, xCuQ — wCu ≥ 3; RESET обнуляет;
// - CTD(CD := xCd, LOAD := xLoad, PV := 2): LOAD ставит 2, фронт CD уменьшает до 0 и не ниже, xCdQ — wCd = 0
//   (WORD без знака: стоит на нуле; проба M0);
// - xRise/xFall — R_TRIG/F_TRIG по xClk; F_TRIG на первом вызове с CLK = FALSE спада не даёт (M0).
FUNCTION_BLOCK FB_Latch
VAR_INPUT
    xSet : BOOL;
    xReset : BOOL;
    xCu : BOOL;
    xCd : BOOL;
    xLoad : BOOL;
    xClk : BOOL;
END_VAR
VAR_OUTPUT
    xSr : BOOL;
    xRs : BOOL;
    xCuQ : BOOL;
    xCdQ : BOOL;
    wCu : WORD;
    wCd : WORD;
    xRise : BOOL;
    xFall : BOOL;
END_VAR
VAR
    fbSr : SR;
    fbRs : RS;
    fbCtu : CTU;
    fbCtd : CTD;
    fbRise : R_TRIG;
    fbFall : F_TRIG;
END_VAR

ST.xhtml:
fbPulse(IN := NOT fbPulse.Q, PT := T#500MS);
xPulse := fbPulse.Q;
xEarly := fbDelay.Q;
fbDelay(IN := xIn, PT := T#1S);
xLate := fbDelay.Q;
xLong := tIn > T#30D;

InterfaceAsPlainText.xhtml:
// FB_TimeIdioms — таймеры промывочного насоса (ST, FUNCTION_BLOCK).
//
// Поведение (модель scenarios/reference/model_FB_TimeIdioms.py):
// - fbPulse(IN := NOT fbPulse.Q, PT := T#500MS) — самосбрасывающийся таймер: Q = TRUE ровно на один вызов,
//   когда ET ≥ 500 мс, следующий вызов сбрасывает таймер (IN = FALSE), ещё следующий — запускает снова;
//   xPulse := fbPulse.Q (C2S7-SEM-TIMER-Q: S7-1200 обновляет Q и при чтении члена);
// - xEarly := fbDelay.Q до вызова fbDelay — значение прошлого вызова; xLate := fbDelay.Q после вызова
//   fbDelay(IN := xIn, PT := T#1S) — TON: Q, когда xIn держится ≥ 1 с;
// - xLong := tIn > T#30D — литерал больше диапазона Time S7 (±24d20h): на S7-1500 → LTime, на S7-1200 —
//   impossible (C2S7-TYPE-TIME). TIME CODESYS — 32 бита без знака.
FUNCTION_BLOCK FB_TimeIdioms
VAR_INPUT
    xIn : BOOL;
    tIn : TIME;
END_VAR
VAR_OUTPUT
    xPulse : BOOL;
    xEarly : BOOL;
    xLate : BOOL;
    xLong : BOOL;
END_VAR
VAR
    fbPulse : TON;
    fbDelay : TON;
END_VAR

// FB_LevelAlarm — сигнализация уровня в фильтре (FBD, 4 сети, Jump/Label).
//
// Поведение (модель scenarios/reference/model_FB_LevelAlarm.py):
// 1. xHigh := rLevel > rHigh;
// 2. если NOT xEnable — переход на lblOut (сеть 3 пропускается, тревога держит прошлое значение);
// 3. xAlarm := (xHigh OR xAlarm) AND NOT xAck — защёлка с квитированием;
// 4. (метка lblOut) xLamp := xAlarm AND xEnable.
FUNCTION_BLOCK FB_LevelAlarm
VAR_INPUT
    rLevel : REAL;
    rHigh : REAL;
    xEnable : BOOL;
    xAck : BOOL;
END_VAR
VAR_OUTPUT
    xAlarm : BOOL;
    xLamp : BOOL;
END_VAR
VAR
    xHigh : BOOL;
END_VAR

// FB_ValveCmd — команда регулирующей задвижки (FBD, MOVE/SEL/LIMIT; EN/ENO не используется — M0: N).
//
// Поведение (модель scenarios/reference/model_FB_ValveCmd.py):
// 1. iCmd := SEL(xOpen, iClosedPos, iOpenPos) — xOpen = FALSE → iClosedPos, TRUE → iOpenPos;
// 2. iPos := LIMIT(iMin, iCmd, iMax);
// 3. iOut := MOVE(iPos);
// 4. xAtLimit := (iPos = iMin) OR (iPos = iMax).
// SEL и LIMIT вне подмножества FlgNet P0 → блок целиком в SCL (C2S7-GFX-SCL).
FUNCTION_BLOCK FB_ValveCmd
VAR_INPUT
    xOpen : BOOL;
    iClosedPos : INT;
    iOpenPos : INT;
    iMin : INT;
    iMax : INT;
END_VAR
VAR_OUTPUT
    iOut : INT;
    xAtLimit : BOOL;
END_VAR
VAR
    iCmd : INT;
    iPos : INT;
END_VAR

// PRG_Permissives — разрешения пуска насоса промывки (LD, PROGRAM: P/N, S/R).
//
// Поведение (модель scenarios/reference/model_PRG_Permissives.py):
// 1. фронт xStartBtn И xPermit → xRun := TRUE (S);
// 2. спад xStopBtn ИЛИ NOT xPermit → xRun := FALSE (R) — сеть 2 после сети 1, сброс побеждает в одном цикле;
// 3. xMotor := xRun AND NOT xFault;
// 4. xIdle := NOT xRun (инверсная катушка).
// Фронты — R_TRIG/F_TRIG CODESYS по переменной; первый вызов: память фронта FALSE.
PROGRAM PRG_Permissives
VAR_INPUT
    xStartBtn : BOOL;
    xStopBtn : BOOL;
    xPermit : BOOL;
    xFault : BOOL;
END_VAR
VAR_OUTPUT
    xRun : BOOL;
    xMotor : BOOL;
    xIdle : BOOL;
END_VAR

// PRG_PumpInterlock — взаимная блокировка насосов II подъёма (LD, PROGRAM: параллели, двойная катушка).
//
// Поведение (модель scenarios/reference/model_PRG_PumpInterlock.py), сети по порядку:
// 1. xP1Run := (xP1Ready AND NOT xP2Run) OR xP1Force;
// 2. xP2Run := (xP2Ready AND NOT xP1Run) OR xP2Force — читает уже новое xP1Run этого цикла;
// 3. xAnyRun := xP1Run OR xP2Run;
// 4. xAlarm := xP1Run AND xP2Run;
// 5. xAlarm := xEmergency — двойная катушка: последняя сеть побеждает (C2S7-GFX-DOUBLECOIL).
PROGRAM PRG_PumpInterlock
VAR_INPUT
    xP1Ready : BOOL;
    xP2Ready : BOOL;
    xP1Force : BOOL;
    xP2Force : BOOL;
    xEmergency : BOOL;
END_VAR
VAR_OUTPUT
    xP1Run : BOOL;
    xP2Run : BOOL;
    xAnyRun : BOOL;
    xAlarm : BOOL;
END_VAR

// FB_PiCfc — ПИ-регулятор расхода промывочной воды (CFC, обратная связь).
//
// Поведение (модель scenarios/reference/model_FB_PiCfc.py), шаги executionOrderId:
// 1. e := rSp − rPv;  2. p := rKp · e;  3. k := rKi · e;
// 4. i := k + i (вход In2 блока ADD — его собственный выход: значение прошлого цикла, начально 0; C2S7-GFX-CFCFB);
// 5. u := p + i;  6. o := LIMIT(rMin, u, rMax);  7. rOut := o.
// Все операции — REAL (float32).
FUNCTION_BLOCK FB_PiCfc
VAR_INPUT
    rSp : REAL;
    rPv : REAL;
    rKp : REAL;
    rKi : REAL;
    rMin : REAL;
    rMax : REAL;
END_VAR
VAR_OUTPUT
    rOut : REAL;
END_VAR

// FB_RatioCfc — соотношение реагента к расходу (CFC, две страницы, порядок не по схеме).
//
// Поведение (модель scenarios/reference/model_FB_RatioCfc.py), шаги executionOrderId:
// 1. rPrev := m — выход MUL читается раньше его шага: значение прошлого вызова (начально 0);
// 2. m := rFlow · rK;  3. rNow := m;  4. s := m + rBias;  5. rSum := s.
// Страница 1 — входы и MUL, страница 2 — сумматор и выходы. REAL (float32).
FUNCTION_BLOCK FB_RatioCfc
VAR_INPUT
    rFlow : REAL;
    rK : REAL;
    rBias : REAL;
END_VAR
VAR_OUTPUT
    rPrev : REAL;
    rNow : REAL;
    rSum : REAL;
END_VAR

// PRG_Backwash — промывка фильтра (SFC, PROGRAM: таймауты, N/S/R/P).
//
// Шаги: Idle (начальный) → [xStart] → Drain → [Drain.t >= T#2S] → Wash → [Wash.t >= T#3S] → Rinse →
// [Rinse.t >= T#1S OR xAbort] → Idle.
// Действия (IEC): Drain — N ActDrain (iDrainTicks += 1), S ActValve (iValveTicks += 1);
// Wash — N ActWash (iWashTicks += 1), P ActCount (iCycles += 1); Rinse — R ActValve, N ActRinse (iRinseTicks += 1).
// Порядок цикла — справка CODESYS (lower/sfc.py); IEC-действие исполняется ещё раз после деактивации
// (последний вызов с Q = FALSE). entry/exit-действия в CODESYS 3.5.17 не импортируются из PLCopen
// (M0: N), поэтому в кейсе их нет — автомат c2s7 их поддерживает (unit-тесты).
PROGRAM PRG_Backwash
VAR_INPUT
    xStart : BOOL;
    xAbort : BOOL;
END_VAR
VAR_OUTPUT
    iDrainTicks : INT;
    iValveTicks : INT;
    iWashTicks : INT;
    iCycles : INT;
    iRinseTicks : INT;
END_VAR

// PRG_FilterAlt — выбор режима фильтрации (SFC, PROGRAM: альтернатива, прыжок, приоритет переходов).
//
// Шаги: Wait (начальный) → альтернатива слева направо: [xHigh] → Fast, [xLow] → Slow (оба TRUE —
// побеждает левый, Fast); Fast → [NOT xHigh] и Slow → [NOT xLow] → Done → [xReset] сходятся и прыжком
// возвращаются на Wait. (Первый вариант — ветви, оканчивающиеся прыжком без схождения, в форме
// tools/corpus/builder.py — CODESYS 3.5.17 при import_xml молча пропустил, 20.10.2026; кейс перестроен.)
// Действия (IEC, N): Fast — ActFast (iFast += 1), Slow — ActSlow (iSlow += 1), Done — ActDone (iDone += 1).
PROGRAM PRG_FilterAlt
VAR_INPUT
    xHigh : BOOL;
    xLow : BOOL;
    xReset : BOOL;
END_VAR
VAR_OUTPUT
    iFast : INT;
    iSlow : INT;
    iDone : INT;
END_VAR

// F_ScaleIL — масштабирование сырого значения датчика мутности (IL, FUNCTION: CAL, CR через ST).
//
// IL в CODESYS 3.5.17 из PLCopen не импортируется (M0: N) — только текстовый корпус для c2s7.sim.
// Поведение (модель scenarios/reference/model_F_ScaleIL.py):
// - результат := (rRaw − rLo) · rK; rTmp := тот же результат (CR переживает ST: «ST rTmp; ST F_ScaleIL»);
// - CAL fbGate(CLK := xGate): R_TRIG внутри FUNCTION инициализируется при каждом вызове, поэтому
//   xGateEdge = xGate (C2S7-POU-FBINFC — ФБ в функции, manual).
FUNCTION F_ScaleIL : REAL
VAR_INPUT
    rRaw : REAL;
    rLo : REAL;
    rK : REAL;
    xGate : BOOL;
END_VAR
VAR_OUTPUT
    xGateEdge : BOOL;
END_VAR
VAR
    rTmp : REAL;
    fbGate : R_TRIG;
END_VAR

// FB_PulseCountIL — накопитель импульсов дозатора (IL, JMPC назад).
//
// IL в CODESYS 3.5.17 из PLCopen не импортируется (M0: N), поэтому кейс — только текстовый корпус для c2s7.sim.
// Поведение (модель scenarios/reference/model_FB_PulseCountIL.py): за вызов iAcc увеличивается на iStep
// ровно iN раз (цикл do-while: тело выполняется хотя бы раз, даже при iN ≤ 0); xOver := iAcc > iMax.
// INT с переносом.
FUNCTION_BLOCK FB_PulseCountIL
VAR_INPUT
    iN : INT;
    iStep : INT;
    iMax : INT;
END_VAR
VAR_OUTPUT
    iAcc : INT;
    xOver : BOOL;
END_VAR
VAR
    i : INT;
END_VAR

ST.xhtml:
iConv := F_Convert(rIn := GVL_IO.rLevel, iA := 1, iB := 2, iSel := 0, iMn := 0, iMx := 100);
fbLatch(xSet := GVL_IO.xStartPb, xReset := GVL_IO.xStopPb);
fbTime(xIn := GVL_IO.xStartPb, tIn := T#1S);
fbLevel(rLevel := GVL_IO.rLevel, rHigh := 2.5, xEnable := TRUE, xAck := GVL_IO.xStopPb);
fbValve(xOpen := GVL_IO.xStartPb, iClosedPos := 0, iOpenPos := 80, iMin := 5, iMax := 95);
fbPi(rSp := 1.0, rPv := GVL_IO.rLevel, rKp := 2.0, rKi := 0.1, rMin := 0.0, rMax := 100.0);
fbRatio(rFlow := GVL_IO.rLevel, rK := 0.5, rBias := 1.0);
eMode := E_FilterMode.Filter;
uStatus.w := GVL_IO.wStatus;
rLvl := GVL_IO.rLevel;
pct := 50;
IF GVL_IO.xStartPb THEN
    GVL_Retain.diBackwashCount := GVL_Retain.diBackwashCount + 1;
END_IF

InterfaceAsPlainText.xhtml:
// Программа-обвязка корпуса: вызывает ФБ и функции, чтобы CODESYS их собрал (в 13 POU не входит).
PROGRAM PRG_Corpus
VAR
    iConv : INT;
    fbLatch : FB_Latch;
    fbTime : FB_TimeIdioms;
    fbLevel : FB_LevelAlarm;
    fbValve : FB_ValveCmd;
    fbPi : FB_PiCfc;
    fbRatio : FB_RatioCfc;
    eMode : E_FilterMode;
    uStatus : U_Status;
    rLvl : T_Level;
    pct : T_Pct;
END_VAR
